import{_ as t,o as e,c as i,a5 as l}from"./chunks/framework.Bt0SrEfo.js";const c=JSON.parse('{"title":"08 AI 协作能力展示","description":"","frontmatter":{"title":"08 AI 协作能力展示"},"headers":[],"relativePath":"前端/engineering/ai-copilot/08-面试与输出.md","filePath":"前端/engineering/ai-copilot/08-面试与输出.md","lastUpdated":1792683759000}'),r={name:"前端/engineering/ai-copilot/08-面试与输出.md"};function o(d,a,h,n,u,s){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="_08-ai-协作能力展示" tabindex="-1">08 AI 协作能力展示 <a class="header-anchor" href="#_08-ai-协作能力展示" aria-label="Permalink to &quot;08 AI 协作能力展示&quot;">​</a></h1><blockquote><p>如何在面试中展示 AI 工程能力，让面试官相信你真的用 AI 做到 95%。</p></blockquote><nav class="table-of-contents"><ul><li><a href="#_8-1-面试的核心叙事">8.1 面试的核心叙事</a><ul><li><a href="#好的回答结构-star-法则">好的回答结构（STAR 法则）</a></li><li><a href="#差的回答">差的回答</a></li><li><a href="#面试追问-深化原-q">面试追问(深化原 Q)</a></li></ul></li><li><a href="#_8-2-展示深度的层次">8.2 展示深度的层次</a></li><li><a href="#_8-3-可以展示的具体场景">8.3 可以展示的具体场景</a><ul><li><a href="#场景-1-pr-自动审查">场景 1：PR 自动审查</a></li><li><a href="#场景-2-自动化检查">场景 2：自动化检查</a></li><li><a href="#场景-3-ai-辅助重构">场景 3：AI 辅助重构</a></li></ul></li><li><a href="#_8-4-面试常见问题及回答">8.4 面试常见问题及回答</a><ul><li><a href="#q1-你用-ai-工具遇到过什么问题">Q1：你用 AI 工具遇到过什么问题？</a></li><li><a href="#q2-ai-生成的代码你怎么保证质量">Q2：AI 生成的代码你怎么保证质量？</a></li><li><a href="#q3-ai-什么时候不靠谱">Q3：AI 什么时候不靠谱？</a></li><li><a href="#q4-你们团队是怎么协作的">Q4：你们团队是怎么协作的？</a></li></ul></li><li><a href="#_8-5-面试加分项">8.5 面试加分项</a></li><li><a href="#_8-6-简历怎么写">8.6 简历怎么写</a></li><li><a href="#学习路径总结">学习路径总结</a></li></ul></nav><h2 id="_8-1-面试的核心叙事" tabindex="-1">8.1 面试的核心叙事 <a class="header-anchor" href="#_8-1-面试的核心叙事" aria-label="Permalink to &quot;8.1 面试的核心叙事&quot;">​</a></h2><p>面试官想听到的不是我会用 Copilot，而是：</p><blockquote><p>我把 AI 工具融入了工程工作流：</p><ul><li>日常代码我用 Copilot 补全，节省 20% 打字时间</li><li>新功能我用 Codex 独立开发，AI 生成 + 我 review + 跑测试</li><li>PR 我用 /autopilot 做自动审查，解决了团队 code review 人手不够的问题</li><li>我还用 Automate 做了每周依赖检查，自动化了以前每周手动做的事</li></ul></blockquote><h3 id="好的回答结构-star-法则" tabindex="-1">好的回答结构（STAR 法则） <a class="header-anchor" href="#好的回答结构-star-法则" aria-label="Permalink to &quot;好的回答结构（STAR 法则）&quot;">​</a></h3><p>S（Situation）：我们团队 code review 占用很多时间 T（Task）：我想把 code review 初筛自动化 A（Action）：我用 Codex /autopilot 做了 PR 自动审查，AI 先扫一遍 R（Result）：人工 review 时间从 30 分钟降到 10 分钟</p><h3 id="差的回答" tabindex="-1">差的回答 <a class="header-anchor" href="#差的回答" aria-label="Permalink to &quot;差的回答&quot;">​</a></h3><p>面试官：你平时怎么用 AI 工具？ 候选人：我就用 Copilot 补全代码，感觉挺方便的。</p><h3 id="面试追问-深化原-q" tabindex="-1">面试追问(深化原 Q) <a class="header-anchor" href="#面试追问-深化原-q" aria-label="Permalink to &quot;面试追问(深化原 Q)&quot;">​</a></h3><ul><li><strong>AI 输出怎么筛选?</strong> 必看:diff、类型、边界条件、副作用;警惕&quot;看起来对但有副作用&quot;的代码</li><li><strong>什么时候不用 AI?</strong> 关键算法、安全敏感、复杂状态机;AI 当草稿,人工 review</li><li><strong>Codex 与 Copilot 区别?</strong> Copilot 自动补全(编辑器内);Codex 任务型(端到端改动)</li><li><strong>AI 编程对未来工程师影响?</strong> 不替代工程师,放大生产力;基础编码能力仍是入场券</li></ul><h2 id="_8-2-展示深度的层次" tabindex="-1">8.2 展示深度的层次 <a class="header-anchor" href="#_8-2-展示深度的层次" aria-label="Permalink to &quot;8.2 展示深度的层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>回答</th><th>面试官感受</th></tr></thead><tbody><tr><td>L1 表层</td><td>我用 Copilot 补全代码</td><td>所有人都会，没亮点</td></tr><tr><td>L2 工具理解</td><td>我给 Copilot 写过 custom instructions</td><td>有一定深度</td></tr><tr><td>L3 工程整合</td><td>我给团队搭了一套 Codex 工作流，PR 创建后 AI 自动审查</td><td>明显超出普通用法</td></tr><tr><td>L4 量化结果</td><td>接入后人工 review 时间减少 60%，CI 失败定位从 15 分钟降到 3 分钟</td><td>有数据，有说服力</td></tr></tbody></table><p>要达到 L3-L4，你需要在真实项目里有实际应用，不是说说而已。</p><h2 id="_8-3-可以展示的具体场景" tabindex="-1">8.3 可以展示的具体场景 <a class="header-anchor" href="#_8-3-可以展示的具体场景" aria-label="Permalink to &quot;8.3 可以展示的具体场景&quot;">​</a></h2><h3 id="场景-1-pr-自动审查" tabindex="-1">场景 1：PR 自动审查 <a class="header-anchor" href="#场景-1-pr-自动审查" aria-label="Permalink to &quot;场景 1：PR 自动审查&quot;">​</a></h3><p>我在团队引入了 Codex /autopilot 来做 PR 初筛：</p><ul><li>PR 创建 to AI 自动分析 diff</li><li>标出类型错误、XSS 风险、重复代码等问题</li><li>AI 在 PR 下评论，说明问题 + 修复建议</li><li>人工只看 AI 标出的高优先级问题</li></ul><p>效果：团队 code review 时间平均减少 40%。</p><h3 id="场景-2-自动化检查" tabindex="-1">场景 2：自动化检查 <a class="header-anchor" href="#场景-2-自动化检查" aria-label="Permalink to &quot;场景 2：自动化检查&quot;">​</a></h3><p>我用 Codex Automate 设置了 3 个定时任务：</p><ol><li>每周一 9:00 检查依赖更新，评估升级风险</li><li>每次 PR 合并前检查 CHANGELOG 是否更新</li><li>CI 失败时自动分析原因，报告给 Slack</li></ol><h3 id="场景-3-ai-辅助重构" tabindex="-1">场景 3：AI 辅助重构 <a class="header-anchor" href="#场景-3-ai-辅助重构" aria-label="Permalink to &quot;场景 3：AI 辅助重构&quot;">​</a></h3><p>我曾经用 Codex 重构了一个 2000 行的老组件：</p><ul><li>AI 分析代码，拆分成 5 个小组件</li><li>AI 生成每个组件的单元测试</li><li>我做 code review，验证重构正确性</li><li>最终把 2000 行压到了 400 行，测试覆盖率从 30% 提到 85%</li></ul><h2 id="_8-4-面试常见问题及回答" tabindex="-1">8.4 面试常见问题及回答 <a class="header-anchor" href="#_8-4-面试常见问题及回答" aria-label="Permalink to &quot;8.4 面试常见问题及回答&quot;">​</a></h2><h3 id="q1-你用-ai-工具遇到过什么问题" tabindex="-1">Q1：你用 AI 工具遇到过什么问题？ <a class="header-anchor" href="#q1-你用-ai-工具遇到过什么问题" aria-label="Permalink to &quot;Q1：你用 AI 工具遇到过什么问题？&quot;">​</a></h3><p>好的回答：最大的问题是上下文不够。AI 一次只能处理有限的文件，超过一定规模的任务，如果不给 AI 足够的上下文，它会生成不连贯的代码。我的解决办法是分批次给 AI 任务，每个批次不超过 5 个相关文件，并在开头给完整的项目背景。</p><h3 id="q2-ai-生成的代码你怎么保证质量" tabindex="-1">Q2：AI 生成的代码你怎么保证质量？ <a class="header-anchor" href="#q2-ai-生成的代码你怎么保证质量" aria-label="Permalink to &quot;Q2：AI 生成的代码你怎么保证质量？&quot;">​</a></h3><p>好的回答：所有 AI 生成的代码必须过三关：第一关 TypeScript 编译（tsc --noEmit），第二关单元测试（jest），第三关我人工 code review。如果测试失败，我会把错误信息反馈给 AI，让它修复后再跑一遍。</p><h3 id="q3-ai-什么时候不靠谱" tabindex="-1">Q3：AI 什么时候不靠谱？ <a class="header-anchor" href="#q3-ai-什么时候不靠谱" aria-label="Permalink to &quot;Q3：AI 什么时候不靠谱？&quot;">​</a></h3><p>好的回答：AI 最大的问题是幻觉，包括引用不存在的 API、生成看起来对但跑不通的代码。所以涉及安全、鉴权、数据库迁移、涉及钱的计算逻辑，我一定不会让 AI 独立做。</p><h3 id="q4-你们团队是怎么协作的" tabindex="-1">Q4：你们团队是怎么协作的？ <a class="header-anchor" href="#q4-你们团队是怎么协作的" aria-label="Permalink to &quot;Q4：你们团队是怎么协作的？&quot;">​</a></h3><p>好的回答：我们有两种模式。异步模式（我用得更多）：我描述任务 to AI 生成代码 to 我 review to 测试 to 合并。Codetime 模式：和 AI 在同一个 editor 里，边做边调整。</p><h2 id="_8-5-面试加分项" tabindex="-1">8.5 面试加分项 <a class="header-anchor" href="#_8-5-面试加分项" aria-label="Permalink to &quot;8.5 面试加分项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>加分项</th><th>说明</th></tr></thead><tbody><tr><td>有数据</td><td>AI 让 XXX 效率提升 X%，最好有具体数字</td></tr><tr><td>有失败经验</td><td>承认踩过坑，说明你真正用过</td></tr><tr><td>有自己的方法论</td><td>我的做法是拆解任务 + AI 执行 + 验证</td></tr><tr><td>能给团队推广</td><td>我给团队分享过 AI 协作经验</td></tr><tr><td>持续跟进</td><td>我关注 AI 编程工具的更新，每个月尝试新工具</td></tr></tbody></table><h2 id="_8-6-简历怎么写" tabindex="-1">8.6 简历怎么写 <a class="header-anchor" href="#_8-6-简历怎么写" aria-label="Permalink to &quot;8.6 简历怎么写&quot;">​</a></h2><p>技术能力：</p><ul><li>AI 协作工程化：用 Codex 实现 PR 自动审查 + CI 失败自动分析，人工 review 时间减少 60%</li><li>熟练使用 Copilot / Codex / Cursor 等 AI 编程工具，日均代码生成量约 30%</li><li>搭建团队 AI 使用规范（AGENTS.md + Code Review AI 初筛流程）</li></ul><p>项目经历（member-h5 会员平台）：</p><ul><li>负责 Web/H5 双端核心页面开发，PWA 缓存优化，缓存命中率提升 40%</li><li>用 Codex Automate 实现每周依赖检查自动化，零人工维护成本</li><li>重构 2000 行组件至 400 行，AI 生成 + 人工验证，测试覆盖率 85%</li></ul><h2 id="学习路径总结" tabindex="-1">学习路径总结 <a class="header-anchor" href="#学习路径总结" aria-label="Permalink to &quot;学习路径总结&quot;">​</a></h2><p>7 天速成计划：</p><p>Day 1-2：概念 + 工具链 — 读完 01 + 02，在 Codex 里开 Thread 练习代码生成 Day 3-4：Codex 基础 + Review — 看完 03 + 04，用 /review 对自己最近的 PR 做一次 AI 审查 Day 5：自动化入门 — 看完 05，用 /loop 设置一个 5 分钟一次的 CI 检查 Day 6-7：多 Agent + 规则 — 看完 06 + 07，给自己的项目写一个 AGENTS.md</p><p>面试前：整理自己的 AI 使用案例（用 STAR 法则），准备 Q1-Q4 的回答，把 AI 能力写进简历</p>',46)])])}const p=t(r,[["render",o]]);export{c as __pageData,p as default};
